"""Visual system for the dashboard: dark navy surfaces, white type, one
restrained blue for data marks (validated: #3987E5 on #111C33 passes the
lightness, chroma and >=3:1 contrast checks). Identity badges always carry a
text label, never colour alone."""
from __future__ import annotations

import html

import plotly.graph_objects as go
import streamlit as st

BG = "#0B1426"
SURFACE = "#111C33"
BORDER = "#1E2C4A"
TEXT = "#FFFFFF"
TEXT_2 = "#B6C2D9"
MUTED = "#7F8BA6"
ACCENT = "#3987E5"
GRID = "#1E2C4A"

# Evidence tiers / statuses: hue + text label (never colour alone).
BADGES = {
    "DIRECT": ("#3987E5", "Direct · internal BMW feedback"),
    "SUPPORTING": ("#199E70", "Supporting · public BMW feedback / BMW study"),
    "CONTEXTUAL": ("#9085E9", "Contextual · competitor observation"),
    "TEMPLATE": ("#7F8BA6", "TEMPLATE · from VFC classifications"),
    "AI_ENRICHED": ("#3987E5", "AI_ENRICHED · uses LLM extraction"),
    "PENDING": ("#C98500", "PENDING · needs further analysis"),
    "REVIEW": ("#C98500", "⚠ Requires review"),
}

CSS = f"""
<style>
  .stApp {{ background: {BG}; }}
  section[data-testid="stSidebar"] {{ background: {SURFACE}; border-right: 1px solid {BORDER}; }}
  .block-container {{ padding-top: 2rem; max-width: 1400px; }}
  h1, h2, h3 {{ letter-spacing: -0.01em; }}
  .pm-sub {{ color: {TEXT_2}; margin-top: -0.6rem; margin-bottom: 1.2rem; }}
  .pm-kpi {{ background: {SURFACE}; border: 1px solid {BORDER}; border-radius: 12px; padding: 16px 18px; height: 100%; }}
  .pm-kpi .v {{ font-size: 2rem; font-weight: 650; color: {TEXT}; line-height: 1.1; }}
  .pm-kpi .l {{ color: {TEXT_2}; font-size: 0.86rem; margin-top: 4px; }}
  .pm-kpi .n {{ color: {MUTED}; font-size: 0.75rem; margin-top: 6px; }}
  .pm-badge {{ display: inline-block; border: 1px solid; border-radius: 999px; padding: 1px 10px; font-size: 0.74rem;
               margin: 0 6px 4px 0; white-space: nowrap; }}
  .pm-chip {{ display: inline-block; background: {BG}; border: 1px solid {BORDER}; border-radius: 6px; padding: 1px 8px;
              font-size: 0.78rem; color: {TEXT_2}; margin: 0 6px 4px 0; }}
  .pm-src {{ color: {MUTED}; font-size: 0.76rem; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }}
  .pm-text {{ color: {TEXT}; font-size: 0.95rem; line-height: 1.5; white-space: pre-wrap; }}
  .pm-note {{ color: {TEXT_2}; font-size: 0.82rem; }}
</style>
"""


def apply_theme() -> None:
    st.markdown(CSS, unsafe_allow_html=True)


def esc(value) -> str:
    return html.escape("" if value is None else str(value))


def badge(kind: str, text: str | None = None) -> str:
    color, label = BADGES[kind]
    return f'<span class="pm-badge" style="color:{color};border-color:{color}">{esc(text or label)}</span>'


def chip(text: str) -> str:
    return f'<span class="pm-chip">{esc(text)}</span>'


def header(title: str, subtitle: str) -> None:
    st.markdown(f"## {esc(title)}")
    st.markdown(f'<div class="pm-sub">{esc(subtitle)}</div>', unsafe_allow_html=True)


def kpi(col, value, label: str, note: str = "") -> None:
    col.markdown(f'<div class="pm-kpi"><div class="v">{esc(value)}</div><div class="l">{esc(label)}</div>'
                 f'<div class="n">{esc(note)}</div></div>', unsafe_allow_html=True)


def bar_chart(labels: list[str], values: list[int], *, value_name: str, extra: list[str] | None = None,
              height: int | None = None) -> go.Figure:
    """Horizontal single-series bar chart (largest at top), one hue, thin bars,
    recessive grid, hover tooltip with the exact value."""
    labels, values = list(reversed(labels)), list(reversed(values))
    custom = list(reversed(extra)) if extra else [""] * len(labels)
    fig = go.Figure(go.Bar(
        x=values, y=labels, orientation="h", marker=dict(color=ACCENT, cornerradius=4), width=0.62,
        customdata=custom,
        hovertemplate=f"<b>%{{y}}</b><br>{value_name}: %{{x:,}}%{{customdata}}<extra></extra>",
    ))
    fig.update_layout(
        height=height or max(220, 34 * len(labels) + 60), margin=dict(l=8, r=16, t=8, b=8),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)", font=dict(color=TEXT_2, size=12),
        xaxis=dict(gridcolor=GRID, zeroline=False, tickformat=",d", title=None),
        yaxis=dict(showgrid=False, title=None, automargin=True, tickfont=dict(color=TEXT)),
        hoverlabel=dict(bgcolor=SURFACE, bordercolor=BORDER, font=dict(color=TEXT)), bargap=0.3,
    )
    return fig

"""Cached data access for the dashboard.

Every loader takes ``db_key`` = "<database path>|<mtime>", so cached results are
invalidated as soon as the database file changes, and also expire after
``TTL_SECONDS``. All data comes from the existing services (no SQL here).
"""
from __future__ import annotations

from pathlib import Path

import streamlit as st

from core.config import get_settings
from core.database import ensure_ai_schema, get_engine, session_scope
from services import dashboard_queries as dq
from services.cross_source_mapping import comments_for_need, evidence_for_need
from services.data_validation import feedback_quality, integrity_checks, provenance_gaps, table_counts
from services.evidence_retrieval import get_feedback_by_ids
from services.feedback_analysis import FeedbackFilter, filter_feedback
from services.evidence_retrieval import search_feedback_text
from services.insight_generator import STATUS_DESCRIPTIONS, all_insight_cards

TTL_SECONDS = 300


def db_path() -> Path:
    return get_settings().database_path.resolve()


def db_key() -> str:
    path = db_path()
    if not path.exists():
        st.error(f"Database not found at {path}. Run `python -m scripts.initialize_database` "
                 "and `python -m scripts.customer_intelligence setup` first.")
        st.stop()
    return f"{path}|{path.stat().st_mtime_ns}"


@st.cache_resource(show_spinner=False)
def _engine(path: str):
    engine = get_engine(Path(path))
    ensure_ai_schema(engine)  # additive only; no-op when up to date
    return engine


def _session(key: str):
    return session_scope(_engine(key.split("|")[0]))


@st.cache_data(ttl=TTL_SECONDS, show_spinner=False)
def filter_options(key: str) -> dict:
    with _session(key) as s:
        return dq.filter_options(s)


@st.cache_data(ttl=TTL_SECONDS, show_spinner="Computing from SQLite…")
def overview(key: str, f_json: str) -> dq.Overview:
    with _session(key) as s:
        return dq.overview(s, dq.DashboardFilter.model_validate_json(f_json))


@st.cache_data(ttl=TTL_SECONDS, show_spinner=False)
def cluster_options(key: str) -> list[dq.ClusterOption]:
    with _session(key) as s:
        return dq.cluster_options(s)


@st.cache_data(ttl=TTL_SECONDS, show_spinner=False)
def mapping_status(key: str) -> dict:
    with _session(key) as s:
        return dq.vfc_mapping_status(s)


@st.cache_data(ttl=TTL_SECONDS, show_spinner="Loading feedback…")
def feedback_page(key: str, f_json: str, search: str, limit: int, offset: int):
    """(total matching comments, records) for the explorer."""
    with _session(key) as s:
        flt: FeedbackFilter = dq.to_feedback_filter(s, dq.DashboardFilter.model_validate_json(f_json))
        if search.strip():
            total, _ = search_feedback_text(s, search, flt, limit=1)
            _, records = search_feedback_text(s, search, flt, limit=offset + limit)
            return total, records[offset:offset + limit]
        page = filter_feedback(s, flt, limit=limit, offset=offset)
        return page.total_feedback_ids, page.items


@st.cache_data(ttl=TTL_SECONDS, show_spinner=False)
def related_evidence(key: str, need_code: str) -> list[dq.EvidenceItem]:
    with _session(key) as s:
        return dq.related_evidence(s, need_code)


@st.cache_data(ttl=TTL_SECONDS, show_spinner=False)
def direct_evidence(key: str, need_code: str):
    with _session(key) as s:
        return evidence_for_need(s, need_code, dq.VEHICLE)


@st.cache_data(ttl=TTL_SECONDS, show_spinner="Loading insights…")
def insight_cards(key: str):
    with _session(key) as s:
        return all_insight_cards(s, dq.VEHICLE)


STATUS_HELP = STATUS_DESCRIPTIONS


@st.cache_data(ttl=TTL_SECONDS, show_spinner="Running data-quality checks…")
def data_quality(key: str) -> dict:
    with _session(key) as s:
        audits = dq.audit_rows(s)
        return {
            "documents": dq.source_documents(s),
            "table_counts": table_counts(s),
            "audits": audits,
            "provenance_gaps": provenance_gaps(s),
            "integrity": integrity_checks(s, get_settings().data_dir, audits),
            "feedback_quality": feedback_quality(s),
            "review_mappings": dq.review_mappings(s),
            "review_links": dq.review_links(s),
            "limitations": dq.known_limitations(s),
        }


@st.cache_data(ttl=TTL_SECONDS, show_spinner=False)
def resolve_feedback(key: str, ids: tuple[str, ...]):
    with _session(key) as s:
        return get_feedback_by_ids(s, list(ids), dq.VEHICLE)


@st.cache_data(ttl=TTL_SECONDS, show_spinner=False)
def need_comment_ids(key: str, need_code: str) -> list[str]:
    with _session(key) as s:
        return comments_for_need(s, need_code, dq.VEHICLE)

