        ev = json.loads(raw)
    except json.JSONDecodeError:
        continue
    if ev.get("type") not in ("user", "assistant") or ev.get("isMeta") or ev.get("isSidechain"):
        continue
    msg = ev.get("message", {})
    role = msg.get("role")
    content = msg.get("content")
    if role == "user":
        if isinstance(content, list) and all(b.get("type") == "tool_result" for b in content):
